APP_SCRIPT += "\nlet skScanClockInterval=null;\nfunction skScanClockText(milliseconds){\n const seconds=Math.max(0,Math.floor(milliseconds/1000));\n const pad=n=>String(n).padStart(2,'0');\n return seconds>=3600?Math.floor(seconds/3600)+':'+pad(Math.floor(seconds/60)%60)+':'+pad(seconds%60):pad(Math.floor(seconds/60))+':'+pad(seconds%60);\n}\nfunction skRenderScanClock(){\n const el=document.getElementById('scan-elapsed'),clock=siteScan?.clock;\n if(!el)return;\n const finished=clock?.state==='complete',banner=$('scan-finished');\n el.hidden=!clock||finished;\n banner.hidden=!finished;\n if(!clock)return;\n const elapsed=Math.max(0,(clock.stoppedAt??Date.now())-clock.startedAt);\n if(finished){\n  const totals=skScanTotals(siteScan);\n  const outcome=!totals.pages?'failed':totals.incomplete?'gaps':'complete';\n  const title=outcome==='failed'?'Scan could not read any pages':'Scan complete';\n  const detail=skScanClockText(elapsed)+' elapsed. '+(outcome==='gaps'?'Some checks need follow-up. Details are in your results.':outcome==='failed'?'See the scan overview for details.':'Your results are ready.');\n  banner.dataset.outcome=outcome;\n  if($('scan-finished-title').textContent!==title)$('scan-finished-title').textContent=title;\n  if($('scan-finished-detail').textContent!==detail)$('scan-finished-detail').textContent=detail;\n  return;\n }\n const label=clock.state==='cancelled'?'Scan cancelled after':clock.state==='paused'?'Elapsed · paused':'Elapsed';\n el.textContent=label+' '+skScanClockText(elapsed);\n el.dataset.state=clock.state;\n}\nfunction skStartScanClock(site){\n const now=Date.now();site.clock||={startedAt:now,stoppedAt:null,state:'running'};\n if(site.clock.stoppedAt!=null){site.clock.startedAt+=now-site.clock.stoppedAt;site.clock.stoppedAt=null;}\n site.clock.state='running';\n clearInterval(skScanClockInterval);skRenderScanClock();\n skScanClockInterval=setInterval(skRenderScanClock,250);\n}\nfunction skFinishScanClock(site){\n const clock=site.clock;if(!clock)return;\n const pending=site.pages.some(p=>['queued','scanning','captured','reviewing'].includes(p.status))||site.pages.some(p=>p.report?.linkChecks?.some(l=>['queued','checking'].includes(l.state)));\n clock.state=site.cancelled?'cancelled':site.pause||pending?'paused':'complete';\n if(clock.state!=='paused'){clock.stoppedAt=Date.now();clearInterval(skScanClockInterval);skScanClockInterval=null;}\n skRenderScanClock();\n}\ndocument.addEventListener('visibilitychange',skRenderScanClock);\n$('scan-view-results').onclick=()=>{\n selectTool('errors');\n const overview=$('site-map');\n overview.tabIndex=-1;\n overview.focus({preventScroll:true});\n overview.scrollIntoView({block:'start'});\n};\n";
