APP_SCRIPT += "\nfunction skIsProductPage(data){\n const html=String(data.html||''),body=html.match(/<body\\b[^>]*class=[\"']([^\"']*)/i)?.[1]||'';\n if(/(?:^|\\s)(?:tax-product_cat|tax-product_tag|template-collection)(?:\\s|$)/i.test(body))return false;\n let path='';try{path=new URL(data.url).pathname}catch{}\n if(/\\/(?:product-category|product_tag|product-tag|collections?)(?:\\/|$)/i.test(path)&&! /\\/products\\/[^/]+/i.test(path))return false;\n return /(?:^|\\s)(?:single-product|template-product)(?:\\s|$)/i.test(body)||/<meta\\b(?=[^>]*(?:property|name)=[\"']og:type[\"'])(?=[^>]*content=[\"'](?:product|product\\.item|og:product)[\"'])[^>]*>/i.test(html)||/\\/(?:products?)\\/[^/]+/i.test(path);\n}\ndocument.getElementById('scan-scope').addEventListener('change',()=>{document.getElementById('skip-catalog').checked=document.getElementById('scan-scope').value==='content'});\n";
