APP_SCRIPT += "\n(function skURLInputGuard(){\n const input=document.getElementById('url'),button=document.getElementById('scan');\n input.maxLength=2048;\n const hint=document.createElement('p');hint.id='url-format-hint';hint.className='fine';hint.hidden=true;hint.textContent='Enter a website address, such as example.com or https://example.com/page.';\n input.setAttribute('aria-describedby',[input.getAttribute('aria-describedby'),hint.id].filter(Boolean).join(' '));document.querySelector('#scan-form .scan-row').after(hint);\n function validate(showHint=false){\n  let valid=false;try{parseWebsiteAddress(input.value);valid=true}catch{}\n  input.setCustomValidity(valid?'':'Enter a valid website address, such as example.com.');\n  if(!siteRunning)button.disabled=!valid;\n  input.setAttribute('aria-invalid',String(!valid&&!!input.value));\n  hint.hidden=valid||!input.value||!showHint;\n  return valid;\n }\n input.addEventListener('input',()=>validate(true));\n input.addEventListener('change',()=>validate(true));\n input.addEventListener('blur',()=>validate(true));\n input.addEventListener('beforeinput',event=>{\n  if(event.isComposing||!event.data||!/[\\s<>\\u0000-\\u001f\\u007f]/.test(event.data))return;\n  event.preventDefault();hint.hidden=false;\n });\n input.addEventListener('paste',event=>{\n  const value=event.clipboardData?.getData('text');if(value==null)return;\n  const clean=value.trim();\n  if(/[\\s<>\\u0000-\\u001f\\u007f]/.test(clean)){event.preventDefault();hint.hidden=false;return}\n  if(clean!==value){event.preventDefault();input.setRangeText(clean,input.selectionStart,input.selectionEnd,'end');input.dispatchEvent(new Event('input',{bubbles:true}));}\n });\n validate();\n})();\n";
