APP_SCRIPT += "\nconst skFindDialog=$('site-find'),skFindInput=$('site-find-query');\nlet skFindTimer,skFindGroups=[],skFindPattern,skFindTotal=0,skFindIndex=0;\nfunction skShowFindMatch(){\n const result=$('site-find-result'),count=$('site-find-count');\n $('site-find-prev').disabled=$('site-find-next').disabled=skFindTotal<2;\n result.hidden=!skFindTotal;\n count.textContent=skFindTotal?(skFindIndex+1)+' of '+skFindTotal+' matches':skFindInput.value?'No matches in scanned text.':'Type to find words or characters.';\n if(!skFindTotal)return;\n let index=skFindIndex;\n const group=skFindGroups.find(group=>{if(index<group.count)return true;index-=group.count;return false});\n skFindPattern.lastIndex=0;\n let match=skFindPattern.exec(group.content);\n for(let i=0;i<index;i++)match=skFindPattern.exec(group.content);\n const start=match.index,end=start+match[0].length;\n const page=$('site-find-page'),snippet=$('site-find-snippet');\n page.textContent=group.url;page.href=group.url;\n snippet.replaceChildren((start>64?'…':'')+group.content.slice(Math.max(0,start-64),start),text('mark',match[0]),group.content.slice(end,end+64)+(end+64<group.content.length?'…':''));\n}\nfunction skSearchSite(){\n clearTimeout(skFindTimer);skFindTimer=null;\n skFindGroups=[];skFindTotal=0;skFindIndex=0;\n const query=skFindInput.value;\n if(query){\n  skFindPattern=new RegExp(query.replace(/[.*+?^\\x24{}()|[\\]\\\\]/g,'\\\\$&'),'giu');\n  for(const {report} of siteScan?.pages||[]){\n   for(const element of report?.page?.elements||[]){\n    const content=element.text||'';\n    skFindPattern.lastIndex=0;\n    let count=0;\n    while(skFindPattern.exec(content))count++;\n    if(count){skFindGroups.push({content,count,url:report.page.url});skFindTotal+=count}\n   }\n  }\n }\n skShowFindMatch();\n}\nfunction skStepFind(direction){\n if(skFindTotal){skFindIndex=(skFindIndex+direction+skFindTotal)%skFindTotal;skShowFindMatch()}\n}\nfunction skOpenSiteFind(){\n if(!skFindDialog.open)skFindDialog.showModal();\n skFindInput.focus();skFindInput.select();skSearchSite();\n}\n$('open-site-find').onclick=skOpenSiteFind;\n$('site-find-prev').onclick=()=>skStepFind(-1);\n$('site-find-next').onclick=()=>skStepFind(1);\nskFindInput.addEventListener('input',()=>{clearTimeout(skFindTimer);skFindTimer=setTimeout(()=>{skFindTimer=null;skSearchSite()},120)});\nskFindDialog.addEventListener('keydown',e=>{\n if(e.key==='Enter'&&e.target===skFindInput&&!e.isComposing){e.preventDefault();if(skFindTimer!=null){clearTimeout(skFindTimer);skFindTimer=null;skSearchSite()}else skStepFind(e.shiftKey?-1:1)}\n});\ndocument.addEventListener('keydown',e=>{\n if(!(e.ctrlKey||e.metaKey)||e.shiftKey||e.altKey||e.key.toLowerCase()!=='f'||!siteScan?.pages.some(p=>p.report?.page?.elements?.length)||document.body.dataset.skExtra||(!skFindDialog.open&&document.querySelector('dialog[open]')))return;\n e.preventDefault();skOpenSiteFind();\n});\n";
